[Form]
public class GUPPriceDiscPriceAttributeGroupEdit extends FormRun
{
    private PriceDiscAdmTrans callerRecord;
    private GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

}

/// <summary>
/// Perform actions at form init
/// </summary>
public void init()
{
    if (!element.args().record() || element.args().dataset() != tableNum(PriceDiscAdmTrans))
    {
        throw error(error::wrongUseOfFunction(funcName()));
    }

    element.initPricingRule();

    super();

    GUPPricingAttributeRepository::getAllPricingAttributes();

    element.enableControls();
    element.disableCancel();
}

/// <summary>
/// Initialize pricing rule for trade agreement depending on source level
/// </summary>
public void initPricingRule()
{
    callerRecord = element.args().record();
    groupCombination = GUPPriceComponentCodePriceAttributeGroupCombination::find(callerRecord.PriceComponentCombination);

    if (!callerRecord.PricingRuleHeader)
    {
        callerRecord.setPricingRuleReference(fieldNum(PriceDiscAdmTrans, PricingRuleHeader), GUPPricingRule::createRule(groupCombination.HeaderPriceAttributeGroupName).RecId);
    }

    if (!callerRecord.PricingRuleLine)
    {
        callerRecord.setPricingRuleReference(fieldNum(PriceDiscAdmTrans, PricingRuleLine), GUPPricingRule::createRule(groupCombination.LinePriceAttributeGroupName).RecId);
    }

    callerRecord.dataSource().research(true);
}

/// <summary>
/// Disable cancel button
/// </summary>
private void disableCancel()
{
    const str parmEdit = 'Edit';

    if (element.args().menuItemName() == menuItemDisplayStr(GUPPriceDiscPriceAttributeGroupEdit)
        && element.args().parm() == parmEdit)
    {
        Cancel.visible(false);
    }
}

/// <summary>
/// Enable/disable controls
/// </summary>
private void enableControls()
{
    boolean allowEditHeader = groupCombination.HeaderGroupAll == GUPGroupAll::Group;
    boolean allowEditLine = groupCombination.LineGroupAll == GUPGroupAll::Group;

    GUPPricingRuleConditionHeader_ds.allowEdit(allowEditHeader);
    PricingRuleConditionsHeader.visible(allowEditHeader);
    GUPPriceDiscPricingRulePreview.visible(allowEditHeader);

    GUPPricingRuleConditionLine_ds.allowEdit(allowEditLine);
    PricingRuleConditionsLine.visible(allowEditLine);
    GUPPriceDiscPricingRulePreviewLine.visible(allowEditLine);        
}

/// <summary>
/// Research parent record when closing
/// </summary>
public void close()
{
    super();

    callerRecord.dataSource().research(true);
}

public void updateRules()
{
    GUPPricingRule::updatePriceAttributeGroup(PriceDiscAdmTrans.PricingRuleHeader, groupCombination.HeaderPriceAttributeGroupName);
    GUPPricingRule::updatePriceAttributeGroup(PriceDiscAdmTrans.PricingRuleLine, groupCombination.LinePriceAttributeGroupName);

    element.enableControls();
}

public void closeOk()
{
    if (!PriceDiscAdmTrans.PriceComponentCombination)
    {
        checkFailed(strFmt("@GlobalUnifiedPricing:GUPPriceComponentCodeEmpty", PriceDiscAdmTrans.LineNum));
    }
    else
    {
        super();
    }
}

public void init()
{
    super();

    QueryBuildDataSource qbdsPriceDiscAdmTrans = PriceDiscAdmTrans_ds.queryBuildDataSource();

    qbdsPriceDiscAdmTrans.clearDynalinks();
    qbdsPriceDiscAdmTrans.clearLinks();

    qbdsPriceDiscAdmTrans.addDynalink(fieldNum(PriceDiscAdmTrans, RecId), callerRecord, fieldNum(PriceDiscAdmTrans, RecId));
}

public display Name displayPricingAttributeName(GUPPricingRuleCondition _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

public edit Name editPricingRuleConditionValue(boolean _set, GUPPricingRuleCondition _ruleCondition, Name _name)
{
    if (_set)
    {
        _ruleCondition.editConditionValue(_name, Checkbox_AppendValueOnLookupHeader.checked());
        _ruleCondition.write();

        GUPPricingAttributeLineState::clearLineState(tableNum(GUPPricingRule), callerRecord.PricingRuleHeader);
    }

    return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
        _ruleCondition.priceAttributeLink().AttributeName,
        _ruleCondition.ConditionValue,
        _ruleCondition.priceAttributeLink());
}

public void init()
{
    super();

    GUPPricingRuleConditionHeader_ds.queryBuildDataSource().addRange(fieldNum(GUPPricingRuleCondition, RuleId)).value(queryValue(callerRecord.PricingRuleHeader));
}

public display Name displayPricingAttributeName(GUPPricingRuleCondition _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

public edit Name editPricingRuleConditionValue(boolean _set, GUPPricingRuleCondition _ruleCondition, Name _name)
{
    if (_set)
    {
        _ruleCondition.editConditionValue(_name, Checkbox_AppendValueOnLookupLine.checked());
        _ruleCondition.write();

        GUPPricingAttributeLineState::clearLineState(tableNum(GUPPricingRule), callerRecord.PricingRuleLine);
    }

    return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
        _ruleCondition.priceAttributeLink().AttributeName,
        _ruleCondition.ConditionValue,
        _ruleCondition.priceAttributeLink());
}

public void init()
{
    super();

    GUPPricingRuleConditionLine_ds.queryBuildDataSource().addRange(fieldNum(GUPPricingRuleCondition, RuleId)).value(queryValue(callerRecord.PricingRuleLine));
}

public Common lookupReference()
{
    SysReferenceTableLookup sysReferenceTableLookup;
    Query                   query = new Query();
    QueryBuildDataSource    qbdsGroupCombination = query.addDataSource(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination));
    QueryBuildDataSource    qbdsComponent;

    sysReferenceTableLookup = SysReferenceTableLookup::newParameters(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination), this);
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Name));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderGroupAll));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LineGroupAll));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroupName));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority));

    qbdsComponent = qbdsGroupCombination.addDataSource(tableNum(GUPPriceComponentCode));
    qbdsComponent.relations(true);
    qbdsComponent.joinMode(JoinMode::ExistsJoin);

    qbdsComponent.addRange(fieldNum(GUPPriceComponentCode, PriceComponent)).value(queryValue(GUPPriceComponent::SalesTradeAgreement));
    qbdsGroupCombination.addOrderByField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority), SortOrder::Descending);

    sysReferenceTableLookup.parmQuery(query);

    return sysReferenceTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret;

    ret = super();

    groupCombination = GUPPriceComponentCodePriceAttributeGroupCombination::find(PriceDiscAdmTrans.PriceComponentCombination);

    GUPPricingRule::updatePriceAttributeGroup(PriceDiscAdmTrans.PricingRuleHeader, groupCombination.HeaderPriceAttributeGroupName);
    GUPPricingRule::updatePriceAttributeGroup(PriceDiscAdmTrans.PricingRuleLine, groupCombination.LinePriceAttributeGroupName);

    element.enableControls();
    PriceDiscAdmTrans_ds.research(true);
    GUPPricingRuleConditionHeader_ds.executeQuery();
    GUPPricingRuleConditionLine_ds.executeQuery();

    return ret;
}

public void lookup()
{
    GUPPricingAttributeAllowedValueLookup::doLookUp(this, GUPPricingRuleConditionHeader.priceAttributeLink());

    super();
}

public void gotFocus()
{
    super();

    // Prohibit customized input for 'fixed value' or 'referenced' price attribute.
    GUPIPricingAttribute priceAttribute = GUPPricingRuleConditionHeader.pricingAttribute();

    if (priceAttribute.getFixedAllowedValueEnumId() != GUPAbstractPricingAttribute::ENUM_ID_NOT_EXIST
        || priceAttribute.getDataType() == AttributeDataType::Reference)
    {
        GUPPricingRuleCondition_ConditionValue.lookupOnly(true);
    }
    else
    {
        GUPPricingRuleCondition_ConditionValue.lookupOnly(false);
    }

    this.replaceOnLookup(true);
}

public void lookup()
{
    GUPPricingAttributeAllowedValueLookup::doLookUp(this, GUPPricingRuleConditionLine.priceAttributeLink());

    super();
}

public void gotFocus()
{
    super();

    // Prohibit customized input for 'fixed value' or 'referenced' price attribute.
    GUPIPricingAttribute priceAttribute = GUPPricingRuleConditionLine.pricingAttribute();

    if (priceAttribute.getFixedAllowedValueEnumId() != GUPAbstractPricingAttribute::ENUM_ID_NOT_EXIST
        || priceAttribute.getDataType() == AttributeDataType::Reference)
    {
        GUPPricingRuleConditionLine_ConditionValue.lookupOnly(true);
    }
    else
    {
        GUPPricingRuleConditionLine_ConditionValue.lookupOnly(false);
    }

    this.replaceOnLookup(true);
}

public void clicked()
{
    FormDataSource fdsCaller = callerRecord.dataSource();

    super();            

    if (element.args().parmEnumType() == enumNum(FormDataSourceEventType)
        && element.args().parmEnum() == FormDataSourceEventType::Created)
    {
        fdsCaller.research(true);
        callerRecord.delete();
    }

    fdsCaller.research(true);
}
